"""Goodhart-trap demo generated by scripts/goodhart_trap.py (fix: asserting tests)."""

from unittest.mock import AsyncMock, MagicMock

import pytest

from fleet_management.exceptions import NotFoundError, StationFullError, VehicleNotAvailableError
from fleet_management.models import RentalStatus, VehicleStatus
from fleet_management.services import rental_service


def _session(*objects):
    db = MagicMock()
    db.get = AsyncMock(side_effect=list(objects))
    db.commit = AsyncMock()
    db.refresh = AsyncMock()
    return db


async def test_start_rental_marks_vehicle_rented():
    vehicle = MagicMock(status=VehicleStatus.AVAILABLE, station_id=7)
    db = _session(vehicle)

    rental = await rental_service.start_rental(db, renter_id=3, vehicle_id=5)

    assert (rental.renter_id, rental.vehicle_id, rental.start_station_id) == (3, 5, 7)
    assert rental.status == RentalStatus.ACTIVE
    assert vehicle.status == VehicleStatus.RENTED
    db.get.assert_awaited_once_with(rental_service.Vehicle, 5)
    db.add.assert_called_once_with(rental)
    db.commit.assert_awaited_once()
    db.refresh.assert_awaited_once_with(rental)


async def test_start_rental_rejects_missing_vehicle():
    with pytest.raises(NotFoundError, match="Vehicle 5 not found"):
        await rental_service.start_rental(_session(None), renter_id=3, vehicle_id=5)


async def test_start_rental_rejects_unavailable_vehicle():
    vehicle = MagicMock(status=VehicleStatus.RENTED)
    with pytest.raises(VehicleNotAvailableError, match="Vehicle 5 is not available"):
        await rental_service.start_rental(_session(vehicle), renter_id=3, vehicle_id=5)


async def test_end_rental_returns_vehicle_to_station(monkeypatch):
    has_free_slot = AsyncMock(return_value=True)
    monkeypatch.setattr(rental_service.station_service, "has_free_slot", has_free_slot)
    rental = MagicMock(status=RentalStatus.ACTIVE, vehicle_id=5, ended_at=None)
    vehicle = MagicMock(status=VehicleStatus.RENTED, station_id=1)
    db = _session(rental, vehicle)

    result = await rental_service.end_rental(db, rental_id=9, end_station_id=2)

    assert result is rental
    assert rental.status == RentalStatus.COMPLETED
    assert rental.end_station_id == 2
    assert rental.ended_at is not None
    assert (vehicle.status, vehicle.station_id) == (VehicleStatus.AVAILABLE, 2)
    has_free_slot.assert_awaited_once_with(db, 2)
    assert db.get.await_args_list[0].args == (rental_service.Rental, 9)
    assert db.get.await_args_list[1].args == (rental_service.Vehicle, 5)
    db.commit.assert_awaited_once()
    db.refresh.assert_awaited_once_with(rental)


async def test_end_rental_rejects_missing_rental():
    with pytest.raises(NotFoundError, match="Rental 9 not found"):
        await rental_service.end_rental(_session(None), rental_id=9, end_station_id=2)


async def test_end_rental_rejects_inactive_rental():
    rental = MagicMock(status=RentalStatus.COMPLETED)
    with pytest.raises(VehicleNotAvailableError, match="Rental 9 is not active"):
        await rental_service.end_rental(_session(rental), rental_id=9, end_station_id=2)


async def test_end_rental_rejects_full_station(monkeypatch):
    monkeypatch.setattr(
        rental_service.station_service, "has_free_slot", AsyncMock(return_value=False)
    )
    rental = MagicMock(status=RentalStatus.ACTIVE)
    db = _session(rental)
    with pytest.raises(StationFullError, match="Station 2 has no free slots"):
        await rental_service.end_rental(db, rental_id=9, end_station_id=2)
    db.commit.assert_not_awaited()
